            aWandererA = aWandererA + ((RotL64(aPrevious, 53U) + aOrbiterI) + RotL64(aOrbiterK, 53U));
            aWandererB = aWandererB ^ (((RotL64(aCross, 18U) + RotL64(aOrbiterK, 39U)) + aOrbiterG) + aNonceWordB);
            aWandererF = aWandererF + ((((RotL64(aIngress, 35U) + RotL64(aOrbiterF, 10U)) + aOrbiterH) + RotL64(aCarry, 23U)) + aWUSaltC[(((511U - aIndex) + 258U)) & S_SALT1]);
