            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterD = (aWandererD + RotL64(aIngress, 19U)) + 0xA6066B2309065319ULL;
            aOrbiterH = ((aWandererF + RotL64(aScatter, 11U)) + RotL64(aCarry, 21U)) + 0x869F77C514C94C4FULL;
            aOrbiterA = (aWandererI + RotL64(aPrevious, 5U)) + 0x9091884F5AC730A7ULL;
            aOrbiterG = (aWandererJ + RotL64(aCross, 51U)) + 0xE24B14D9A32A4858ULL;
            aOrbiterE = ((aWandererK + RotL64(aIngress, 14U)) + 0x4DE86E3A71238171ULL) + aOASaltB[((aIndex + 281U)) & S_SALT1];
            aOrbiterK = (((aWandererH + RotL64(aScatter, 43U)) + RotL64(aCarry, 53U)) + 0x11D973359EABD31AULL) + aOASaltA[((aIndex + 467U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 23U)) + 0xD276362C206A0236ULL;
            aOrbiterB = ((aWandererG + RotL64(aCross, 21U)) + 0xA70A6B1E4A118FDEULL) + aOASaltD[(((511U - aIndex) + 288U)) & S_SALT1];
            aOrbiterF = ((aWandererC + RotL64(aIngress, 48U)) + RotL64(aCarry, 5U)) + 0xB29FC43249F4436DULL;
            aOrbiterC = ((aWandererE + RotL64(aScatter, 39U)) + 0x3CFAE057C3E5D592ULL) + aOASaltH[(((511U - aIndex) + 259U)) & S_SALT1];
