            aOrbiterI = ((aWandererC + RotL64(aIngress, 39U)) + 0xA702914556C101DDULL) + aOASaltE[(((511U - aIndex) + 495U)) & S_SALT1];
            aOrbiterB = ((aWandererJ + RotL64(aScatter, 60U)) + 0x17DE88211DD2219EULL) + aOASaltC[((aIndex + 39U)) & S_SALT1];
            aOrbiterE = (((aWandererG + RotL64(aPrevious, 11U)) + RotL64(aCarry, 53U)) + 0xF5111BCA6B88D254ULL) + aOASaltA[(((511U - aIndex) + 233U)) & S_SALT1];
