            aOrbiterF = RotL64((aOrbiterF * 0x6449E7B06D9D9CC3ULL), 53U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xC87BB032E31B3276ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0x49EF371690856BEFULL) ^ aOUSaltA[((aIndex + 155U)) & S_SALT1];
