            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x864450C28922E525ULL) + aOUSaltD[((aIndex + 371U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xE571FD3232325B48ULL;
